    /// ADR-0035 metering: the census must (a) classify advertisers by
    /// bootstrap membership via ADDRESS overlap with the operator fleet,
    /// (b) skip TTL-stale entries — a dead relay advert would otherwise
    /// inflate the community pool and mask the centralization skew the
    /// rollout is measuring.
    #[tokio::test]
    async fn relay_census_classifies_bootstrap_and_skips_stale() {
        let agent = Agent::builder()
            .with_network_config(network::NetworkConfig::default())
            .build()
            .await
            .unwrap();
        let now = Agent::unix_timestamp_secs();
        let mk = |id: u8, addr: &str, relay: bool, coord: bool, last_seen: u64| DiscoveredAgent {
            self_name: None,
            agent_id: identity::AgentId([id; 32]),
            machine_id: identity::MachineId([id; 32]),
            user_id: None,
            addresses: vec![addr.parse().unwrap()],
            announced_at: last_seen,
            last_seen,
            machine_public_key: vec![1],
            nat_type: None,
            can_receive_direct: Some(relay),
            is_relay: Some(relay),
            is_coordinator: Some(coord),
            reachable_via: vec![],
            relay_candidates: vec![],
            cert_not_after: None,
            agent_certificate: None,
            agent_public_key: vec![],
            cert_digest: None,
        };
        // Bootstrap-hosted relay (NYC bootstrap IP), community relay,
        // community coordinator, and a STALE community relay.
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            mk(1, "142.93.199.50:443", true, true, now),
        )
        .await;
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            mk(2, "203.0.113.9:5483", true, false, now),
        )
        .await;
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            mk(3, "203.0.113.10:5483", false, true, now),
        )
        .await;
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            mk(
                4,
                "203.0.113.11:5483",
                true,
                true,
                now.saturating_sub(90_000),
            ),
        )
        .await;

        let census = agent.relay_census().await;
        assert_eq!(census.relay_advertised, 2, "stale relay must not count");
        assert_eq!(census.relay_on_bootstrap, 1);
        assert_eq!(census.relay_non_bootstrap, 1);
        assert_eq!(census.coordinator_advertised, 2);
        assert_eq!(census.coordinator_on_bootstrap, 1);
        assert_eq!(census.coordinator_non_bootstrap, 1);
        assert!(census.agents_live >= 3);
    }

    #[tokio::test]
    async fn upsert_promotes_certificate_into_existing_cert_less_entry() {
        // WHY (ADR-0038 review finding 5): a V3 announce whose blob fetch
        // was still in flight inserts a cert-less entry; heartbeats keep it
        // alive (last_seen refreshes). Without promotion, the entry stays
        // cert-less FOREVER and OwnerCertified evidence destructively
        // evicts a valid member as NoCertificate. A later announce carrying
        // the resolved certificate must promote it into the existing entry.
        let agent = Agent::builder()
            .with_network_config(network::NetworkConfig::default())
            .build()
            .await
            .unwrap();
        let now = Agent::unix_timestamp_secs();
        let user = identity::UserKeypair::generate().unwrap();
        let member = identity::AgentKeypair::generate().unwrap();
        let cert = identity::AgentCertificate::issue(&user, &member).unwrap();
        let mk = |last_seen: u64, cert: Option<identity::AgentCertificate>| DiscoveredAgent {
            agent_id: member.agent_id(),
            machine_id: identity::MachineId([9; 32]),
            user_id: None,
            self_name: None,
            addresses: vec![],
            announced_at: last_seen,
            last_seen,
            machine_public_key: vec![1],
            nat_type: None,
            can_receive_direct: None,
            is_relay: None,
            is_coordinator: None,
            reachable_via: vec![],
            relay_candidates: vec![],
            cert_not_after: cert.as_ref().and_then(|c| c.not_after()),
            agent_certificate: cert,
            agent_public_key: vec![],
            cert_digest: None,
        };
        // Cold miss: cert-less entry lands first.
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            mk(now, None),
        )
        .await;
        // Later heartbeat, same agent, now with the fetched certificate.
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            mk(now + 5, Some(cert.clone())),
        )
        .await;
        let cache = agent.identity_discovery_cache.read().await;
        let entry = cache.get(&member.agent_id()).expect("entry retained");
        assert!(
            entry.agent_certificate.as_ref().is_some_and(|c| c == &cert),
            "the fetched certificate must be promoted into the existing entry"
        );
        // And a cert-less later announce must NOT demote it.
        drop(cache);
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            mk(now + 10, None),
        )
        .await;
        let cache = agent.identity_discovery_cache.read().await;
        let entry = cache.get(&member.agent_id()).expect("entry retained");
        assert!(
            entry.agent_certificate.is_some(),
            "promotion is monotone: a cert-less announce never clears evidence"
        );
        // Round-2 freshness coupling: an announce committing to a DIFFERENT
        // digest re-keys the agent's claim — the cached cert predates it and
        // must be dropped (evidence reads a retryable NoCertificate until the
        // new blob lands) instead of being trusted blindly.
        drop(cache);
        let mut rekeyed = mk(now + 15, None);
        rekeyed.cert_digest = Some([0xAA; 32]);
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            rekeyed,
        )
        .await;
        let cache = agent.identity_discovery_cache.read().await;
        let entry = cache.get(&member.agent_id()).expect("entry retained");
        assert!(
            entry.agent_certificate.is_none(),
            "a new announced digest must invalidate the stale cached certificate"
        );
        assert_eq!(entry.cert_digest, Some([0xAA; 32]));
    }

    /// E2d (design v6/v7): a certificate LANDING in the identity-discovery
    /// cache must fire exactly one [`VerifiedCertificate`] event per CHANGE
    /// — the server bridge's hydration trigger. An identical re-announce
    /// (the 600 s heartbeat re-carries the same cert) must NOT re-fire, and
    /// the digest must equal `owner_cert::certificate_digest_hex`.
    #[tokio::test]
    async fn verified_certificate_events_fire_on_landing_not_on_replay() {
        let agent = Agent::builder()
            .with_network_config(network::NetworkConfig::default())
            .build()
            .await
            .unwrap();
        let mut events = agent.subscribe_verified_certificates();
        let user = identity::UserKeypair::generate().unwrap();
        let member = identity::AgentKeypair::generate().unwrap();
        let cert = identity::AgentCertificate::issue(&user, &member).unwrap();
        let now = Agent::unix_timestamp_secs();
        let mk = |last_seen: u64, cert: Option<identity::AgentCertificate>| DiscoveredAgent {
            agent_id: member.agent_id(),
            machine_id: identity::MachineId([9; 32]),
            user_id: None,
            self_name: None,
            addresses: vec![],
            announced_at: last_seen,
            last_seen,
            machine_public_key: vec![1],
            nat_type: None,
            can_receive_direct: None,
            is_relay: None,
            is_coordinator: None,
            reachable_via: vec![],
            relay_candidates: vec![],
            cert_not_after: cert.as_ref().and_then(|c| c.not_after()),
            agent_certificate: cert,
            agent_public_key: vec![],
            cert_digest: None,
        };

        // Cold insert carrying the certificate → one event.
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            mk(now, Some(cert.clone())),
        )
        .await;
        let event = events.recv().await.expect("cold landing fires an event");
        assert_eq!(event.agent_id, member.agent_id());
        assert_eq!(event.certificate, cert);
        assert_eq!(
            event.digest_hex(),
            groups::owner_cert::certificate_digest_hex(&cert),
            "event digest must match the seat-digest rule byte-for-byte"
        );

        // Identical re-announce (same bytes, fresher timestamp) → NO event.
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            mk(now + 5, Some(cert.clone())),
        )
        .await;
        assert!(
            events.try_recv().is_err(),
            "an identical re-announce must not re-fire the hydration bridge"
        );

        // Promote into an existing cert-less entry → one event (blob-landing
        // shape: entry first lands digest-only, the fetch completes later).
        let other = identity::AgentKeypair::generate().unwrap();
        let other_cert = identity::AgentCertificate::issue(&user, &other).unwrap();
        let mut cold = mk(now, None);
        cold.agent_id = other.agent_id();
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            cold,
        )
        .await;
        let mut warmed = mk(now + 1, Some(other_cert.clone()));
        warmed.agent_id = other.agent_id();
        upsert_discovered_agent(
            &agent.identity_discovery_cache,
            &agent.verified_cert_tx,
            warmed,
        )
        .await;
        let promoted = events.recv().await.expect("promotion fires an event");
        assert_eq!(promoted.agent_id, other.agent_id());
        assert_eq!(promoted.certificate, other_cert);
    }

    #[tokio::test]
    async fn discovery_cache_insertion_is_hard_capped() {
        // WHY (round-2 finding 7): Sybil announcements must not grow the
        // live identity cache without bound — every OwnerCertified evidence
        // pass walks it. At the cap the stalest entry is evicted.
        let agent = Agent::builder()
            .with_network_config(network::NetworkConfig::default())
            .build()
            .await
            .unwrap();
        let now = Agent::unix_timestamp_secs();
        let mk = |id: u8, last_seen: u64| DiscoveredAgent {
            agent_id: identity::AgentId([id; 32]),
            machine_id: identity::MachineId([id; 32]),
            user_id: None,
            self_name: None,
            addresses: vec![],
            announced_at: last_seen,
            last_seen,
            machine_public_key: vec![1],
            nat_type: None,
            can_receive_direct: None,
            is_relay: None,
            is_coordinator: None,
            reachable_via: vec![],
            relay_candidates: vec![],
            cert_not_after: None,
            agent_certificate: None,
            agent_public_key: vec![],
            cert_digest: None,
        };
        // Fill past the cap with distinct agents (byte ids wrap but the
        // full [u8;32] arrays stay distinct via the index).
        for i in 0..=(DISCOVERY_CACHE_MAX_ENTRIES as u16) {
            let mut id = [0u8; 32];
            id[..2].copy_from_slice(&i.to_be_bytes());
            let mut entry = mk(0, now + u64::from(i));
            entry.agent_id = identity::AgentId(id);
            entry.machine_id = identity::MachineId(id);
            upsert_discovered_agent(
                &agent.identity_discovery_cache,
                &agent.verified_cert_tx,
                entry,
            )
            .await;
        }
        let cache = agent.identity_discovery_cache.read().await;
        assert!(
            cache.len() <= DISCOVERY_CACHE_MAX_ENTRIES,
            "cache must stay capped, got {}",
            cache.len()
        );
    }

    /// ADR-0035 metering: selection-skew classification — machine id →
    /// discovery-cache addresses → bootstrap-IP bridge. The :443/:5483
    /// port rows for the same bootstrap host must classify identically
    /// (IP dedupe), community addresses classify NonBootstrap, and an
    /// unknown machine id classifies NoneAvailable.
    #[tokio::test]
    async fn selection_skew_classifies_bootstrap_community_and_unknown() {
        let mkm = |id: u8, addr: &str| DiscoveredMachine {
            machine_id: identity::MachineId([id; 32]),
            addresses: vec![addr.parse().unwrap()],
            announced_at: 1,
            last_seen: 1,
            machine_public_key: vec![1],
            nat_type: None,
            can_receive_direct: Some(true),
            is_relay: Some(true),
            is_coordinator: Some(false),
            reachable_via: vec![],
            relay_candidates: vec![],
            machine_kem_public_key: None,
            placement_digests: Vec::new(),
            agent_ids: vec![],
            user_ids: vec![],
        };
        let cache: tokio::sync::RwLock<
            std::collections::HashMap<identity::MachineId, DiscoveredMachine>,
        > = tokio::sync::RwLock::new(std::collections::HashMap::new());
        // Bootstrap host via the :5483 row, another bootstrap host via :443.
        cache
            .write()
            .await
            .insert(identity::MachineId([1; 32]), mkm(1, "142.93.199.50:5483"));
        cache
            .write()
            .await
            .insert(identity::MachineId([2; 32]), mkm(2, "147.182.234.192:443"));
        // Community machine.
        cache
            .write()
            .await
            .insert(identity::MachineId([3; 32]), mkm(3, "203.0.113.9:5483"));

        let ips = bootstrap_ip_set();
        assert!(
            classify_relay_choice(&cache, &ips, &identity::MachineId([1; 32])).await
                == SelectionChoice::Bootstrap,
            "the :5483 row of a bootstrap host classifies bootstrap"
        );
        assert!(
            classify_relay_choice(&cache, &ips, &identity::MachineId([2; 32])).await
                == SelectionChoice::Bootstrap,
            "the :443 row of a bootstrap host classifies bootstrap"
        );
        assert!(
            classify_relay_choice(&cache, &ips, &identity::MachineId([3; 32])).await
                == SelectionChoice::NonBootstrap,
            "a community address classifies non-bootstrap"
        );
        assert!(
            classify_relay_choice(&cache, &ips, &identity::MachineId([9; 32])).await
                == SelectionChoice::NoneAvailable,
            "an unknown machine id classifies none-available"
        );
    }

    /// ADR-0035 metering: counters are monotone under interleaved records
    /// and the snapshot reflects every class.
    #[tokio::test]
    async fn selection_skew_counters_are_monotone() {
        let skew = SelectionSkew::default();
        let before = skew.snapshot();
        assert_eq!(before, SelectionSkewSnapshot::default());

        skew.record(SelectionChoice::Bootstrap);
        skew.record(SelectionChoice::Bootstrap);
        skew.record(SelectionChoice::NonBootstrap);
        skew.record(SelectionChoice::NoneAvailable);

        let after = skew.snapshot();
        assert_eq!(after.chosen_bootstrap, 2);
        assert_eq!(after.chosen_non_bootstrap, 1);
        assert_eq!(after.none_available, 1);
        assert!(after.chosen_bootstrap >= before.chosen_bootstrap);
        assert!(after.chosen_non_bootstrap >= before.chosen_non_bootstrap);
        assert!(after.none_available >= before.none_available);
    }

    /// SEAM PIN (envelope-blindness lesson): the snapshot's serde JSON —
    /// what `/diagnostics/relay` emits — must expose exactly the three
    /// counter keys the ADR-0035 dashboard reads. If this drifts from the
    /// route consumer, the dashboard silently shows zeros.
    #[test]
    fn selection_skew_snapshot_json_contract() {
        let skew = SelectionSkew::default();
        skew.record(SelectionChoice::NonBootstrap);
        let json = serde_json::to_value(skew.snapshot()).expect("snapshot serializes");
        let obj = json.as_object().expect("snapshot is a JSON object");
        assert_eq!(obj.len(), 3, "exactly three counters on the wire");
        for key in ["chosen_bootstrap", "chosen_non_bootstrap", "none_available"] {
            assert!(obj.contains_key(key), "counter {key} must be on the wire");
        }
        assert_eq!(obj["chosen_non_bootstrap"], serde_json::json!(1));
    }

    /// L3 retirement flip: by default (legacy_announce == false) an announce
    /// publishes ONLY the V3 format — no V2 identity payload and no separate
    /// machine announcement reach the wire. If this regresses, the fleet
    /// silently returns to 3 broadcast messages per beat and the entire L3
    /// bandwidth win evaporates.
    #[tokio::test]
    async fn retired_announce_publishes_v3_only() {
        let agent = Agent::builder()
            .with_network_config(network::NetworkConfig::default())
            .build()
            .await
            .unwrap();
        let runtime = agent.gossip_runtime.as_ref().expect("gossip runtime");
        let mut identity_sub = runtime
            .pubsub()
            .subscribe(IDENTITY_ANNOUNCE_TOPIC.to_string())
            .await;
        let mut machine_sub = runtime
            .pubsub()
            .subscribe(MACHINE_ANNOUNCE_TOPIC.to_string())
            .await;

        agent.announce_identity(false, false).await.unwrap();

        // Collect everything that arrives within the settle window.
        let mut v3 = 0usize;
        let mut v2_or_legacy = 0usize;
        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(3);
        while tokio::time::Instant::now() < deadline {
            tokio::select! {
                Some(msg) = identity_sub.recv() => {
                    if announce_v3::is_v3_payload(&msg.payload) {
                        let ann = announce_v3::deserialize_v3(&msg.payload).expect("v3 decodes");
                        ann.verify().expect("published v3 verifies");
                        v3 += 1;
                    } else {
                        v2_or_legacy += 1;
                    }
                }
                Some(_) = machine_sub.recv() => {
                    panic!("retired announce must not publish a machine announcement");
                }
                _ = tokio::time::sleep_until(deadline) => break,
            }
        }
        assert!(v3 >= 1, "retired announce must publish at least one V3");
        assert_eq!(
            v2_or_legacy, 0,
            "retired announce must not publish V2/legacy identity payloads"
        );
    }

    /// ADR-0036: an agent with a self-name set announces it on the V3 beat
    /// (verified end-to-end through the real publish path), and an unnamed
    /// agent's V3 payload carries no name — the two states peers must be
    /// able to distinguish.
    #[tokio::test]
    async fn named_agent_announces_self_name_on_v3_beat() {
        let agent = Agent::builder()
            .with_network_config(network::NetworkConfig::default())
            .build()
            .await
            .unwrap();
        let runtime = agent.gossip_runtime.as_ref().expect("gossip runtime");
        let mut identity_sub = runtime
            .pubsub()
            .subscribe(IDENTITY_ANNOUNCE_TOPIC.to_string())
            .await;

        // Unnamed beat first: X0A3 only.
        agent.announce_identity(false, false).await.unwrap();
        // Then set the name the way `PUT /profile` does and beat again: the
        // named beat must dual-publish X0A4 (name) + the X0A3 companion.
        agent.set_self_name(Some("fae".to_string()));
        agent.announce_identity(false, false).await.unwrap();
        // Then CLEAR the name: the ever-named latch keeps X0A4 publishing,
        // now with an explicit no-name (the clear signal for peers).
        agent.set_self_name(None);
        agent.announce_identity(false, false).await.unwrap();

        let mut x0a3_unnamed = 0usize;
        let mut saw_named = false;
        let mut saw_cleared = false;
        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(3);
        while tokio::time::Instant::now() < deadline
            && !(x0a3_unnamed >= 2 && saw_named && saw_cleared)
        {
            tokio::select! {
                Some(msg) = identity_sub.recv() => {
                    if announce_v3::is_v3_payload(&msg.payload) {
                        let is_v31 = msg.payload
                            .starts_with(announce_v3::IDENTITY_ANNOUNCEMENT_V3_1_MAGIC);
                        let v3 = announce_v3::deserialize_v3(&msg.payload).expect("v3 decodes");
                        v3.verify().expect("published v3 verifies");
                        match (is_v31, v3.self_name.as_deref()) {
                            (false, None) => x0a3_unnamed += 1,
                            (true, Some("fae")) => saw_named = true,
                            (true, None) => saw_cleared = true,
                            other => panic!("unexpected (envelope, self_name) on beat: {other:?}"),
                        }
                    }
                }
                _ = tokio::time::sleep_until(deadline) => break,
            }
        }
        assert!(
            x0a3_unnamed >= 1,
            "unnamed beat must publish X0A3 without a self_name"
        );
        assert!(
            saw_named,
            "named beat must publish X0A4 carrying the self_name"
        );
        assert!(
            x0a3_unnamed >= 2,
            "named beat must dual-publish the legacy X0A3 companion (review P0: old peers' decoders reject grown bodies and V2 is retired)"
        );
        assert!(
            saw_cleared,
            "a cleared name must keep publishing X0A4 with an explicit no-name              (review R2: clears must propagate, not age out)"
        );
    }

    /// The escape hatch (`with_legacy_announce(true)`) restores the V2 set —
    /// V2 identity AND machine announcements alongside V3 — for debugging and
    /// isolated pre-V3 networks.
    #[tokio::test]
    async fn legacy_escape_hatch_publishes_v2_and_v3() {
        let agent = Agent::builder()
            .with_network_config(network::NetworkConfig::default())
            .with_legacy_announce(true)
            .build()
            .await
            .unwrap();
        let runtime = agent.gossip_runtime.as_ref().expect("gossip runtime");
        let mut identity_sub = runtime
            .pubsub()
            .subscribe(IDENTITY_ANNOUNCE_TOPIC.to_string())
            .await;
        let mut machine_sub = runtime
            .pubsub()
            .subscribe(MACHINE_ANNOUNCE_TOPIC.to_string())
            .await;

        agent.announce_identity(false, false).await.unwrap();

        let mut v3 = 0usize;
        let mut v2 = 0usize;
        let mut machine = 0usize;
        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(3);
        while tokio::time::Instant::now() < deadline {
            tokio::select! {
                Some(msg) = identity_sub.recv() => {
                    if announce_v3::is_v3_payload(&msg.payload) {
                        v3 += 1;
                    } else if deserialize_identity_announcement(&msg.payload).is_ok() {
                        v2 += 1;
                    }
                }
                Some(msg) = machine_sub.recv() => {
                    if deserialize_machine_announcement(&msg.payload).is_ok() {
                        machine += 1;
                    }
                }
                _ = tokio::time::sleep_until(deadline) => break,
            }
        }
        assert!(v3 >= 1, "escape hatch still publishes V3");
        assert!(v2 >= 1, "escape hatch publishes V2 identity");
        assert!(machine >= 1, "escape hatch publishes machine announcement");
    }

    /// Enforcement point 2 (issue #130): a revoked agent MUST fail
    /// `is_agent_machine_verified` even when its signed identity announcement
    /// is still sitting verified in the discovery cache. This is the DM/gate
    /// denial property — a revoked peer is refused everywhere the daemon asks
    /// "is this (agent, machine) binding trustworthy?". The revocation is
    /// applied via the real `verify_and_insert` receive path (the same call
    /// the gossip subscription makes on receipt), and the subject is
    /// self-revoked (issuer key == subject agent-id, valid authority).
    #[tokio::test]
    async fn revoked_agent_fails_machine_verification_even_when_cached() {
        let user_key = identity::UserKeypair::generate().unwrap();
        let agent = Agent::builder()
            .with_network_config(network::NetworkConfig::default())
            .with_user_key(user_key)
            .build()
            .await
            .unwrap();

        // Seed the discovery cache with our own signed announcement so the
        // (agent, machine) binding verifies true BEFORE revocation.
        agent.announce_identity(true, true).await.unwrap();
        let agent_id = agent.agent_id();
        let machine_id = agent.machine_id();
        assert!(
            agent
                .is_agent_machine_verified(&agent_id, &machine_id)
                .await,
            "a cached, signed self-announcement must verify before revocation"
        );

        // Apply a valid SELF-revocation of our own agent-id via the real
        // receive path. verify_and_insert re-checks the ML-DSA signature and
        // the self-revocation authority rule, exactly as on gossip receipt.
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        let record = revocation::RevocationRecord::sign(
            revocation::RevokedSubject::Agent(agent_id),
            agent.identity().agent_keypair().public_key(),
            agent.identity().agent_keypair().secret_key(),
            now,
            Some("ep2 test: key compromised".to_string()),
        )
        .unwrap();
        {
            let set = agent.revocation_set();
            let mut set = set.write().await;
            set.verify_and_insert(record, None)
                .expect("self-revocation must verify and insert");
        }

        // Fail-closed: the verified gate must now refuse the revoked agent,
        // even though its announcement is still cached and otherwise valid.
        assert!(
            !agent
                .is_agent_machine_verified(&agent_id, &machine_id)
                .await,
            "a revoked agent must never pass machine verification while cached"
        );
    }

    /// Issue #191 gap 2: a gossiped **issuer-revocation** (a user un-vouching
    /// a certified agent) MUST propagate over gossip. The gossip wire carries
    /// bare `RevocationRecord`s (no certs), so the receiver resolves the
    /// subject cert from its discovery cache — via `collect_subject_certs`,
    /// the exact lookup the gossip-receive loop now performs — and passes it
    /// to `verify_and_insert`. Pre-fix the loop passed `None`, and
    /// `verify_authority` rejects an issuer-revocation without a cert, so only
    /// self-revocations ever propagated network-wide.
    #[test]
    fn issuer_revocation_propagates_over_gossip_via_cache_cert_lookup() {
        let user = identity::UserKeypair::generate().unwrap();
        let issued_agent = identity::AgentKeypair::generate().unwrap();
        let agent_id = issued_agent.agent_id();
        // The user vouches for the agent — this cert is what authorizes a
        // later issuer-revocation (verify_authority checks the issuer key is
        // the certifying user).
        let cert = identity::AgentCertificate::issue(&user, &issued_agent).unwrap();

        // Seed the discovery cache exactly as EP1 does on a real announcement:
        // the cert is retained so a gossiped issuer-revocation can be verified.
        let mut cache = std::collections::HashMap::new();
        cache.insert(
            agent_id,
            DiscoveredAgent {
                self_name: None,
                agent_id,
                machine_id: identity::MachineId([0u8; 32]),
                user_id: None,
                addresses: Vec::new(),
                announced_at: 0,
                last_seen: 0,
                machine_public_key: Vec::new(),
                nat_type: None,
                can_receive_direct: None,
                is_relay: None,
                is_coordinator: None,
                reachable_via: Vec::new(),
                relay_candidates: Vec::new(),
                cert_not_after: cert.not_after(),
                agent_certificate: Some(cert.clone()),
                agent_public_key: cert.agent_public_key().to_vec(),
                cert_digest: None,
            },
        );

        // The gossip-receive path resolves subject certs from the cache.
        let subject_certs = collect_subject_certs(&cache);
        let looked_up = subject_certs
            .get(&agent_id)
            .expect("the cache lookup must find the subject cert");

        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        // The user revokes the agent it vouched for (issuer-revocation).
        let record = revocation::RevocationRecord::sign(
            revocation::RevokedSubject::Agent(agent_id),
            user.public_key(),
            user.secret_key(),
            now,
            Some("issuer revokes compromised agent".to_string()),
        )
        .unwrap();

        // With the cache-resolved cert, the issuer-revocation verifies +
        // inserts (the post-fix gossip behavior).
        let mut set = revocation::RevocationSet::new();
        assert!(
            set.verify_and_insert(record.clone(), Some(looked_up))
                .unwrap(),
            "issuer-revocation must verify and insert with the cache-resolved cert"
        );
        assert!(
            set.is_agent_revoked(&agent_id),
            "the agent must now be revoked network-wide"
        );

        // Pre-fix proof: without the cert (the old `None` gossip path), an
        // issuer-revocation is REJECTED by verify_authority — which is exactly
        // why issuer-revocations were inert over gossip before this fix.
        assert!(
            revocation::RevocationSet::new()
                .verify_and_insert(record, None)
                .is_err(),
            "an issuer-revocation must be rejected without the subject cert \
             (the pre-fix gossip behavior this closes)"
        );
    }

    /// An announcement without NAT fields (as produced by old nodes) should still
    /// deserialise correctly via bincode — new fields are `Option` so `None` (0x00)
    /// is a valid encoding.
    #[test]
    fn identity_announcement_backward_compat_no_nat_fields() {
        use identity::{AgentId, MachineId};

        // Build an announcement that omits the nat_* fields by serializing an old-style
        // struct that matches the pre-1.3 wire format.
        #[derive(serde::Serialize, serde::Deserialize)]
        struct OldIdentityAnnouncementUnsigned {
            agent_id: AgentId,
            machine_id: MachineId,
            user_id: Option<identity::UserId>,
            agent_certificate: Option<identity::AgentCertificate>,
            machine_public_key: Vec<u8>,
            addresses: Vec<std::net::SocketAddr>,
            announced_at: u64,
        }

        let agent_id = AgentId([1u8; 32]);
        let machine_id = MachineId([2u8; 32]);
        let old = OldIdentityAnnouncementUnsigned {
            agent_id,
            machine_id,
            user_id: None,
            agent_certificate: None,
            machine_public_key: vec![0u8; 10],
            addresses: Vec::new(),
            announced_at: 1234,
        };
        let bytes = bincode::serialize(&old).expect("serialize old announcement");

        // Attempt to deserialize as the new struct — this tests that the new fields
        // (which are Option<T>) do NOT break deserialization of the old format.
        // Note: bincode 1.x is not self-describing, so adding fields to a struct DOES
        // change the wire format.  This test documents the expected behavior.
        // Old format -> new struct: will fail because new struct has more fields.
        // New format -> old struct: will have trailing bytes.
        // This is acceptable — we document the protocol change.
        let result = bincode::deserialize::<IdentityAnnouncementUnsigned>(&bytes);
        // Old nodes produce shorter messages; new nodes cannot decode them as new structs.
        // This confirms the protocol is not transparent — nodes must upgrade together.
        assert!(
            result.is_err(),
            "Old-format announcement should not decode as new struct (protocol upgrade required)"
        );
    }

    #[tokio::test]
    async fn register_announced_machine_skips_self_agent() {
        // The daemon must never create a contact entry for its own agent: a
        // self record is noise on `/contacts` and makes contact-set
        // assertions racy (issue #145). A self-announcement is refused even
        // though it carries a valid (agent, machine) pair.
        let dir = tempfile::tempdir().expect("tmpdir");
        let store = std::sync::Arc::new(tokio::sync::RwLock::new(contacts::ContactStore::new(
            dir.path().join("contacts.json"),
        )));
        let own = identity::AgentId([1u8; 32]);
        let own_machine = identity::MachineId([2u8; 32]);

        let added = super::register_announced_machine(&store, own, own, own_machine).await;

        assert!(!added, "self-announcement must not register a machine");
        let store = store.read().await;
        assert!(
            store.machines(&own).is_empty(),
            "self-agent must have no machine record after a self-announcement"
        );
        // Stronger invariant: the daemon must have NO contact entry at all
        // for its own agent, not merely an empty machine list. add_machine
        // creates the Contact shell on first sight (contacts.rs:423), so this
        // confirms the self-skip happens before that insertion (#145).
        assert!(
            store.list().iter().all(|contact| contact.agent_id != own),
            "self-agent must not appear in the contact store at all after a \
             self-announcement"
        );
    }

    #[tokio::test]
    async fn register_announced_machine_registers_foreign_agent() {
        // Foreign observation must keep registering a machine record so peers
        // remain observable in the contact surface — the self-skip must not be
        // over-broad. A second announcement of the same (agent, machine) is
        // idempotent (returns false, no duplicate record).
        let dir = tempfile::tempdir().expect("tmpdir");
        let store = std::sync::Arc::new(tokio::sync::RwLock::new(contacts::ContactStore::new(
            dir.path().join("contacts.json"),
        )));
        let own = identity::AgentId([1u8; 32]);
        let peer = identity::AgentId([9u8; 32]);
        let peer_machine = identity::MachineId([7u8; 32]);

        let added = super::register_announced_machine(&store, own, peer, peer_machine).await;
        assert!(added, "foreign announcement must register a new machine");

        let added_again = super::register_announced_machine(&store, own, peer, peer_machine).await;
        assert!(
            !added_again,
            "re-announcing the same machine must be idempotent"
        );

        let store = store.read().await;
        let machines = store.machines(&peer);
        assert_eq!(machines.len(), 1, "exactly one machine record");
        assert_eq!(machines[0].machine_id, peer_machine);
        assert!(
            store.machines(&own).is_empty(),
            "own agent must still have no contact entry"
        );
    }

    #[test]
    fn announcement_assist_snapshot_uses_capabilities_not_activity() {
        // #398: this test's original fixture (services on, everything else
        // defaulted) now honestly yields relay/coordinator = Some(false):
        // capability requires PLAUSIBLY-PUBLIC reachability in addition to
        // the service, and the default NodeStatus has neither peer-verified
        // global scope nor a port mapping. The reachability signal is added
        // to the fixture so the capability-vs-activity distinction (the
        // point of this test) stays under test.
        let status = ant_quic::NodeStatus {
            nat_type: ant_quic::NatType::FullCone,
            can_receive_direct: true,
            direct_reachability_scope: Some(ant_quic::ReachabilityScope::Global),
            relay_service_enabled: true,
            coordinator_service_enabled: true,
            is_relaying: false,
            is_coordinating: false,
            ..Default::default()
        };

        let snapshot = AnnouncementAssistSnapshot::from_node_status(&status);
        assert_eq!(snapshot.nat_type.as_deref(), Some("Full Cone"));
        assert_eq!(snapshot.can_receive_direct, Some(true));
        assert_eq!(snapshot.relay_capable, Some(true));
        assert_eq!(snapshot.coordinator_capable, Some(true));
        assert_eq!(snapshot.relay_active, Some(false));
        assert_eq!(snapshot.coordinator_active, Some(false));
    }

    /// A new announcement with all NAT fields set round-trips through bincode.
    #[test]
    fn identity_announcement_nat_fields_round_trip() {
        use identity::{AgentId, MachineId};

        let unsigned = IdentityAnnouncementUnsigned {
            agent_id: AgentId([1u8; 32]),
            machine_id: MachineId([2u8; 32]),
            user_id: None,
            agent_certificate: None,
            machine_public_key: vec![0u8; 10],
            addresses: Vec::new(),
            announced_at: 9999,
            nat_type: Some("FullCone".to_string()),
            can_receive_direct: Some(true),
            is_relay: Some(false),
            is_coordinator: Some(true),
            reachable_via: vec![MachineId([5u8; 32])],
            relay_candidates: vec![MachineId([6u8; 32])],
        };
        let bytes = bincode::serialize(&unsigned).expect("serialize");
        let decoded: IdentityAnnouncementUnsigned =
            bincode::deserialize(&bytes).expect("deserialize");
        assert_eq!(decoded.nat_type.as_deref(), Some("FullCone"));
        assert_eq!(decoded.can_receive_direct, Some(true));
        assert_eq!(decoded.is_relay, Some(false));
        assert_eq!(decoded.is_coordinator, Some(true));
        assert_eq!(decoded.reachable_via, vec![MachineId([5u8; 32])]);
        assert_eq!(decoded.relay_candidates, vec![MachineId([6u8; 32])]);
    }

    #[tokio::test]
    async fn announcement_decode_helpers_match_bincode_serialize_wire_format() {
        let temp = tempfile::tempdir().unwrap();
        let agent = Agent::builder()
            .with_machine_key(temp.path().join("machine.key"))
            .with_agent_key_path(temp.path().join("agent.key"))
            .with_agent_cert_path(temp.path().join("agent.cert"))
            .with_contact_store_path(temp.path().join("contacts.json"))
            .build()
            .await
            .unwrap();

        let identity = agent.build_identity_announcement(false, false).unwrap();
        let identity_bytes = serialize_identity_announcement(&identity).unwrap();
        let decoded_identity = deserialize_identity_announcement(&identity_bytes).unwrap();
        assert_eq!(decoded_identity.agent_id, identity.agent_id);
        assert_eq!(decoded_identity.machine_id, identity.machine_id);
        // The v2 envelope must carry the agent public key (#204).
        assert_eq!(decoded_identity.agent_public_key, identity.agent_public_key);
        assert!(
            !decoded_identity.agent_public_key.is_empty(),
            "v2 announcement must carry the agent public key"
        );
        let machine = agent.build_machine_announcement().unwrap();
        let machine_bytes = bincode::serialize(&machine).unwrap();
        let decoded_machine = deserialize_machine_announcement(&machine_bytes).unwrap();
        assert_eq!(decoded_machine.machine_id, machine.machine_id);
        assert_eq!(decoded_machine.addresses, machine.addresses);
    }

    #[tokio::test]
    async fn deserialize_identity_announcement_rejects_trailing_bytes() {
        let temp = tempfile::tempdir().unwrap();
        let agent = Agent::builder()
            .with_machine_key(temp.path().join("machine.key"))
            .with_agent_key_path(temp.path().join("agent.key"))
            .with_agent_cert_path(temp.path().join("agent.cert"))
            .with_contact_store_path(temp.path().join("contacts.json"))
            .build()
            .await
            .unwrap();

        let announcement = agent.build_identity_announcement(false, false).unwrap();
        let mut bytes = bincode::serialize(&announcement).unwrap();
        bytes.extend_from_slice(&[0xde, 0xad, 0xbe, 0xef]);

        assert!(
            deserialize_identity_announcement(&bytes).is_err(),
            "identity announcements with trailing bytes must be rejected"
        );
    }

    /// An announcement with None for all NAT fields (e.g. network not started)
    /// round-trips correctly.
    #[test]
    fn identity_announcement_no_nat_fields_round_trip() {
        use identity::{AgentId, MachineId};

        let unsigned = IdentityAnnouncementUnsigned {
            agent_id: AgentId([3u8; 32]),
            machine_id: MachineId([4u8; 32]),
            user_id: None,
            agent_certificate: None,
            machine_public_key: vec![0u8; 10],
            addresses: Vec::new(),
            announced_at: 42,
            nat_type: None,
            can_receive_direct: None,
            is_relay: None,
            is_coordinator: None,
            reachable_via: Vec::new(),
            relay_candidates: Vec::new(),
        };
        let bytes = bincode::serialize(&unsigned).expect("serialize");
        let decoded: IdentityAnnouncementUnsigned =
            bincode::deserialize(&bytes).expect("deserialize");
        assert!(decoded.nat_type.is_none());
        assert!(decoded.can_receive_direct.is_none());
        assert!(decoded.is_relay.is_none());
        assert!(decoded.is_coordinator.is_none());
        assert!(decoded.reachable_via.is_empty());
        assert!(decoded.relay_candidates.is_empty());
    }

    /// Wire format v2 populates coordinator-hint fields: full round-trip and
    /// deterministic signing.
    #[test]
    fn identity_announcement_reachable_via_round_trip() {
        use identity::{AgentId, MachineId};

        let coord_a = MachineId([0xAAu8; 32]);
        let coord_b = MachineId([0xBBu8; 32]);
        let unsigned = IdentityAnnouncementUnsigned {
            agent_id: AgentId([9u8; 32]),
            machine_id: MachineId([8u8; 32]),
            user_id: None,
            agent_certificate: None,
            machine_public_key: vec![0u8; 10],
            addresses: Vec::new(),
            announced_at: 555,
            nat_type: Some("Symmetric".to_string()),
            can_receive_direct: Some(false),
            is_relay: Some(false),
            is_coordinator: Some(false),
            reachable_via: vec![coord_a, coord_b],
            relay_candidates: vec![coord_a],
        };
        let bytes = bincode::serialize(&unsigned).expect("serialize");
        let decoded: IdentityAnnouncementUnsigned =
            bincode::deserialize(&bytes).expect("deserialize");
        assert_eq!(decoded.reachable_via, vec![coord_a, coord_b]);
        assert_eq!(decoded.relay_candidates, vec![coord_a]);

        // Mutating reachable_via MUST invalidate the outer sig — signing over
        // the unsigned form guarantees integrity. Here we only verify the
        // bincode is stable; cryptographic coverage lives in the existing
        // `identity_announcement_machine_signature_verifies` tests.
        let re_encoded = bincode::serialize(&decoded).expect("re-serialize");
        assert_eq!(
            bytes, re_encoded,
            "canonical bincode round-trip must be stable"
        );
    }

    #[test]
    fn user_announcement_sign_and_verify() {
        let user_kp = identity::UserKeypair::generate().unwrap();
        let agent_kp_a = identity::AgentKeypair::generate().unwrap();
        let agent_kp_b = identity::AgentKeypair::generate().unwrap();
        let cert_a = identity::AgentCertificate::issue(&user_kp, &agent_kp_a).unwrap();
        let cert_b = identity::AgentCertificate::issue(&user_kp, &agent_kp_b).unwrap();

        let announcement = UserAnnouncement::sign(&user_kp, vec![cert_a, cert_b], 1234).unwrap();
        announcement.verify().expect("freshly-signed must verify");
        assert_eq!(announcement.user_id, user_kp.user_id());
        assert_eq!(announcement.agent_certificates.len(), 2);
    }

    #[test]
    fn deserialize_user_announcement_rejects_trailing_bytes() {
        let user_kp = identity::UserKeypair::generate().unwrap();
        let agent_kp = identity::AgentKeypair::generate().unwrap();
        let cert = identity::AgentCertificate::issue(&user_kp, &agent_kp).unwrap();
        let announcement = UserAnnouncement::sign(&user_kp, vec![cert], 1234).unwrap();
        let mut bytes = bincode::serialize(&announcement).unwrap();
        bytes.extend_from_slice(&[0xde, 0xad, 0xbe, 0xef]);

        assert!(
            deserialize_user_announcement(&bytes).is_err(),
            "user announcements with trailing bytes must be rejected"
        );
    }

    #[test]
    fn user_announcement_rejects_foreign_certificate() {
        let user_kp = identity::UserKeypair::generate().unwrap();
        let other_user = identity::UserKeypair::generate().unwrap();
        let agent_kp = identity::AgentKeypair::generate().unwrap();
        // Certificate issued by `other_user` — we should refuse to include it
        // in a roster signed by `user_kp`.
        let foreign_cert = identity::AgentCertificate::issue(&other_user, &agent_kp).unwrap();
        let err = UserAnnouncement::sign(&user_kp, vec![foreign_cert], 0).unwrap_err();
        assert!(
            err.to_string().contains("different user"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn user_announcement_tampered_agent_cert_list_fails() {
        let user_kp = identity::UserKeypair::generate().unwrap();
        let agent_kp = identity::AgentKeypair::generate().unwrap();
        let cert = identity::AgentCertificate::issue(&user_kp, &agent_kp).unwrap();

        let mut announcement = UserAnnouncement::sign(&user_kp, vec![cert], 10).unwrap();
        // Forge an additional certificate from a different user into the list.
        let other_user = identity::UserKeypair::generate().unwrap();
        let other_agent = identity::AgentKeypair::generate().unwrap();
        let foreign_cert = identity::AgentCertificate::issue(&other_user, &other_agent).unwrap();
        announcement.agent_certificates.push(foreign_cert);
        assert!(
            announcement.verify().is_err(),
            "announcement with appended foreign cert must fail verification"
        );
    }

    #[test]
    fn user_announcement_tampered_user_public_key_fails() {
        let user_kp = identity::UserKeypair::generate().unwrap();
        let agent_kp = identity::AgentKeypair::generate().unwrap();
        let cert = identity::AgentCertificate::issue(&user_kp, &agent_kp).unwrap();
        let mut announcement = UserAnnouncement::sign(&user_kp, vec![cert], 10).unwrap();
        let other = identity::UserKeypair::generate().unwrap();
        announcement.user_public_key = other.public_key().as_bytes().to_vec();
        assert!(announcement.verify().is_err());
    }

