    receiver
        .insert_discovered_agent_for_testing(discovered)
        .await;
    assert!(receiver.cached_agent(&origin.agent_id()).await.is_some());

    receiver
        .evict_revoked_subject(&revocation::RevokedSubject::Machine(machine.machine_id()))
