// ---------------------------------------------------------------------------
// Restart-safe FenceToken: restart-epoch ABA fence (unit tests)
// ---------------------------------------------------------------------------
//
// FenceToken combines a per-replica epoch (regenerated on daemon restart via
// `fresh_epoch`) with the local revision. The handle accepts a caller's token
// only when BOTH match its current `(epoch, revision)` — i.e. exactly when
// `expected == current`. These tests pin that equality contract: an identical
// revision under a DIFFERENT epoch is rejected (closes the restart-ABA window
// without persisting task state), and a moved revision at the same epoch is
// rejected (stale local snapshot). The wire encoding is opaque to clients.

#[cfg(test)]
mod fence_token_tests {
    use crate::FenceToken;

    #[test]
    fn wire_roundtrip_preserves_epoch_and_revision() {
        let token = FenceToken {
            epoch: 123,
            revision: 456,
        };
        let wire = token.to_wire();
        let back = FenceToken::from_wire(&wire).expect("roundtrip parses");
        assert_eq!(back, token);
    }

    #[test]
    fn from_wire_returns_err_for_malformed_and_overflow_tokens() {
        // `from_wire` returns Result: a present-but-malformed/overflow token is
        // `Err`, which the PATCH handler maps to 400 BAD_REQUEST (non-mutating).
        // This is distinct from an ABSENT token (still a valid unfenced advisory
        // commit). A corrupt/legacy/overflow token can never bypass the guard or
        // silently downgrade to "no fence".
        assert!(FenceToken::from_wire("").is_err());
        assert!(FenceToken::from_wire("no-colon").is_err());
        assert!(FenceToken::from_wire(":5").is_err(), "missing epoch");
        assert!(FenceToken::from_wire("1:").is_err(), "missing revision");
        assert!(FenceToken::from_wire("1:2:3").is_err(), "too many parts");
        assert!(FenceToken::from_wire("abc:2").is_err(), "non-numeric epoch");
        assert!(
            FenceToken::from_wire("1:xyz").is_err(),
            "non-numeric revision"
        );
        // Integer overflow beyond u64 must be Err, not wrapped/truncated to a
        // bogus token that could ABA-match a real one.
        assert!(
            FenceToken::from_wire("999999999999999999999999999999:1").is_err(),
            "epoch overflow must be rejected"
        );
        assert!(
            FenceToken::from_wire("1:999999999999999999999999999999").is_err(),
            "revision overflow must be rejected"
        );
        // Teeth check: a well-formed token still parses to Ok, so the parser
        // rejects malformed input specifically, not all input.
        let ok = FenceToken::from_wire("123:456");
        assert!(ok.is_ok(), "well-formed token must parse");
        assert_eq!(
            ok.unwrap(),
            FenceToken {
                epoch: 123,
                revision: 456
            }
        );
    }

    #[test]
    fn same_revision_different_epoch_is_stale_the_restart_aba_breaker() {
        // The handle regenerates its epoch on restart (fresh_epoch). A token
        // captured BEFORE a restart carries the pre-restart epoch; even if the
        // revision counter later reaches the SAME value post-restart, the
        // epoch differs ⇒ the token is rejected. This is the restart-ABA fence.
        let pre_restart = FenceToken {
            epoch: 100,
            revision: 42,
        };
        let post_restart_same_revision = FenceToken {
            epoch: 999,
            revision: 42,
        };
        assert_ne!(
            pre_restart, post_restart_same_revision,
            "epoch differs ⇒ stale even at an identical revision (ABA safe)"
        );
        // An exact (epoch, revision) match is accepted.
        let current = FenceToken {
            epoch: 999,
            revision: 42,
        };
        assert_eq!(post_restart_same_revision, current, "exact match accepts");
    }

    #[test]
    fn stale_revision_at_same_epoch_is_stale() {
        // Within one epoch (no restart), a moved local snapshot (revision
        // advanced) also rejects the caller's stale token.
        let stale = FenceToken {
            epoch: 7,
            revision: 3,
        };
        let current = FenceToken {
            epoch: 7,
            revision: 4,
        };
        assert_ne!(stale, current, "revision moved ⇒ token is stale");
    }
}

/// Tests for issue #304 (inbound peer address in machine_discovery_cache) and
/// issue #308 (per-machine address cap, MRU recency, MRU-first reconnect).
#[cfg(test)]
mod candidate_address_retention_tests {
    use super::{
        reconnect_candidate_addrs, upsert_discovered_machine, DiscoveredMachine,
        MAX_DISCOVERED_MACHINE_ADDRESSES, RECONNECT_CANDIDATE_DIAL_TIMEOUT,
    };
    use crate::identity::MachineId;
    use std::sync::Arc;
    use tokio::sync::RwLock;

    fn observation(
        machine_id: MachineId,
        addresses: Vec<std::net::SocketAddr>,
        last_seen: u64,
    ) -> DiscoveredMachine {
        DiscoveredMachine {
            machine_id,
            addresses,
            // PeerConnected observations use announced_at: 0 so they add/refresh
            // one addr and never LWW-wipe reachable_via / relay_candidates.
            announced_at: 0,
            last_seen,
            machine_public_key: Vec::new(),
            nat_type: None,
            can_receive_direct: None,
            is_relay: None,
            is_coordinator: None,
            reachable_via: Vec::new(),
            relay_candidates: Vec::new(),
            machine_kem_public_key: None,
            placement_digests: Vec::new(),
            agent_ids: Vec::new(),
            user_ids: Vec::new(),
        }
    }

    /// Verify that upsert_discovered_machine with a connection-derived record
    /// correctly populates the cache so the reconnect path reads candidate_addrs > 0.
    ///
    /// This encodes WHY: before fix #304 the PeerConnected handler did NOT call
    /// upsert_discovered_machine, so a peer known only via an inbound connection
    /// had candidate_addrs=0 on redial and the LAN dial was skipped entirely.
    #[tokio::test]
    async fn peer_connected_address_appears_in_machine_discovery_cache() {
        let cache: Arc<RwLock<std::collections::HashMap<MachineId, DiscoveredMachine>>> =
            Arc::new(RwLock::new(std::collections::HashMap::new()));

        let peer_id = [0x42u8; 32];
        let machine_id = MachineId(peer_id);
        let address: std::net::SocketAddr = "192.168.1.108:5493".parse().unwrap();

        // Cache starts empty — candidate_addrs would be 0 before the fix.
        assert!(
            cache.read().await.is_empty(),
            "cache must start empty for this test to prove anything"
        );

        // Simulate what the PeerConnected handler now does (fix #304).
        let now_s = crate::dm::now_unix_ms() / 1000;
        upsert_discovered_machine(
            &cache,
            DiscoveredMachine {
                machine_id,
                addresses: vec![address],
                announced_at: now_s,
                last_seen: now_s,
                machine_public_key: Vec::new(),
                nat_type: None,
                can_receive_direct: None,
                is_relay: None,
                is_coordinator: None,
                reachable_via: Vec::new(),
                relay_candidates: Vec::new(),
                machine_kem_public_key: None,
                placement_digests: Vec::new(),
                agent_ids: Vec::new(),
                user_ids: Vec::new(),
            },
        )
        .await;

        // The reconnect path reads: cache.get(&machine_id).map(|m| m.addresses.clone())
        let candidate_addrs = {
            let guard = cache.read().await;
            guard
                .get(&machine_id)
                .map(|m| m.addresses.clone())
                .unwrap_or_default()
        };

        assert_eq!(
            candidate_addrs.len(),
            1,
            "reconnect candidate set must be non-empty after a connection is established"
        );
        assert_eq!(
            candidate_addrs[0], address,
            "candidate address must be the peer's observed remote address"
        );
    }

    /// Verify that the 0.0.0.0:0 placeholder from the accept loop (when remote_addr
    /// is not a UDP socket) is NOT inserted into the cache. Inserting it would cause
    /// all reconnect dials to attempt 0.0.0.0:0 and fail, producing noise.
    #[tokio::test]
    async fn zero_placeholder_address_is_not_recorded() {
        let cache: Arc<RwLock<std::collections::HashMap<MachineId, DiscoveredMachine>>> =
            Arc::new(RwLock::new(std::collections::HashMap::new()));

        let machine_id = MachineId([0x01u8; 32]);
        let zero_addr: std::net::SocketAddr = "0.0.0.0:0".parse().unwrap();

        // Call the SAME predicate the PeerConnected handler gates on, rather
        // than duplicating its expression here -- a copy would keep passing if
        // the production guard were broken.
        if super::observed_address_is_dialable(&zero_addr) {
            let now_s = crate::dm::now_unix_ms() / 1000;
            upsert_discovered_machine(
                &cache,
                DiscoveredMachine {
                    machine_id,
                    addresses: vec![zero_addr],
                    announced_at: now_s,
                    last_seen: now_s,
                    machine_public_key: Vec::new(),
                    nat_type: None,
                    can_receive_direct: None,
                    is_relay: None,
                    is_coordinator: None,
                    reachable_via: Vec::new(),
                    relay_candidates: Vec::new(),
                    machine_kem_public_key: None,
                    placement_digests: Vec::new(),
                    agent_ids: Vec::new(),
                    user_ids: Vec::new(),
                },
            )
            .await;
        }

        assert!(
            cache.read().await.is_empty(),
            "0.0.0.0:0 placeholder must not be inserted into machine_discovery_cache"
        );

        // Defense in depth: upsert itself must refuse the placeholder even
        // if a caller skips the PeerConnected predicate.
        upsert_discovered_machine(&cache, observation(machine_id, vec![zero_addr], 1)).await;
        let addrs = {
            let guard = cache.read().await;
            guard
                .get(&machine_id)
                .map(|m| m.addresses.clone())
                .unwrap_or_default()
        };
        assert!(
            addrs.is_empty(),
            "upsert must never store an unspecified or port-0 address"
        );
    }

    /// Verify address deduplication: calling upsert twice for the same machine
    /// at the same address does not duplicate the address entry.
    #[tokio::test]
    async fn repeated_connection_does_not_duplicate_addresses() {
        let cache: Arc<RwLock<std::collections::HashMap<MachineId, DiscoveredMachine>>> =
            Arc::new(RwLock::new(std::collections::HashMap::new()));

        let machine_id = MachineId([0x33u8; 32]);
        let address: std::net::SocketAddr = "10.0.0.1:5483".parse().unwrap();
        let now_s = crate::dm::now_unix_ms() / 1000;

        // Upsert twice — simulates two consecutive connections.
        for _ in 0..2 {
            upsert_discovered_machine(
                &cache,
                DiscoveredMachine {
                    machine_id,
                    addresses: vec![address],
                    announced_at: now_s,
                    last_seen: now_s,
                    machine_public_key: Vec::new(),
                    nat_type: None,
                    can_receive_direct: None,
                    is_relay: None,
                    is_coordinator: None,
                    reachable_via: Vec::new(),
                    relay_candidates: Vec::new(),
                    machine_kem_public_key: None,
                    placement_digests: Vec::new(),
                    agent_ids: Vec::new(),
                    user_ids: Vec::new(),
                },
            )
            .await;
        }

        let guard = cache.read().await;
        let entry = guard.get(&machine_id).expect("entry must exist");
        assert_eq!(
            entry.addresses.len(),
            1,
            "upsert must deduplicate: same address inserted twice must produce one entry"
        );
    }

    /// WHY: mobile / symmetric-NAT peers present a new source port on every
    /// reconnect. Without a cap the list grows without bound and reconnect
    /// pays 5s per dead candidate (issue #308). Newest observed wins; eviction
    /// drops the least-recently-seen addr, not "first in the vec" after sort.
    #[tokio::test]
    async fn twenty_observed_ports_keep_the_eight_most_recent() {
        let cache: Arc<RwLock<std::collections::HashMap<MachineId, DiscoveredMachine>>> =
            Arc::new(RwLock::new(std::collections::HashMap::new()));

        let machine_id = MachineId([0x08u8; 32]);
        let mut observed = Vec::with_capacity(20);
        for port in 1u16..=20 {
            let addr = std::net::SocketAddr::from((std::net::Ipv4Addr::new(192, 0, 2, 1), port));
            observed.push(addr);
            upsert_discovered_machine(&cache, observation(machine_id, vec![addr], u64::from(port)))
                .await;
        }

        let guard = cache.read().await;
        let entry = guard.get(&machine_id).expect("entry must exist");
        assert_eq!(
            entry.addresses.len(),
            MAX_DISCOVERED_MACHINE_ADDRESSES,
            "20 distinct observed ports must evict down to the per-machine cap"
        );
        let expected = observed[observed.len() - MAX_DISCOVERED_MACHINE_ADDRESSES..].to_vec();
        assert_eq!(
            entry.addresses, expected,
            "retained addresses must be the 8 most recently observed, in LRU→MRU order"
        );
        for stale in &observed[..observed.len() - MAX_DISCOVERED_MACHINE_ADDRESSES] {
            assert!(
                !entry.addresses.contains(stale),
                "least-recently-seen {stale} must be evicted, not merely shifted"
            );
        }
    }

    /// WHY: a PeerConnected observation (announced_at: 0) must add/refresh
    /// that one addr without last-write-wins wiping coordinator/relay hints
    /// that a prior signed announcement installed (issue #304 / #308).
    #[tokio::test]
    async fn inbound_observe_does_not_wipe_announced_reachability_hints() {
        let cache: Arc<RwLock<std::collections::HashMap<MachineId, DiscoveredMachine>>> =
            Arc::new(RwLock::new(std::collections::HashMap::new()));

        let machine_id = MachineId([0x30u8; 32]);
        let announced: std::net::SocketAddr = "198.51.100.1:5483".parse().unwrap();
        let observed: std::net::SocketAddr = "192.168.1.50:5493".parse().unwrap();
        let coord = MachineId([0xAAu8; 32]);
        let relay = MachineId([0xBBu8; 32]);

        upsert_discovered_machine(
            &cache,
            DiscoveredMachine {
                machine_id,
                addresses: vec![announced],
                announced_at: 1_700_000_000,
                last_seen: 1_700_000_000,
                machine_public_key: Vec::new(),
                nat_type: None,
                can_receive_direct: Some(false),
                is_relay: None,
                is_coordinator: None,
                reachable_via: vec![coord],
                relay_candidates: vec![relay],
                machine_kem_public_key: None,
                placement_digests: Vec::new(),
                agent_ids: Vec::new(),
                user_ids: Vec::new(),
            },
        )
        .await;

        upsert_discovered_machine(
            &cache,
            observation(machine_id, vec![observed], 1_700_000_100),
        )
        .await;

        let guard = cache.read().await;
        let entry = guard.get(&machine_id).expect("entry must exist");
        assert!(
            entry.addresses.contains(&announced) && entry.addresses.contains(&observed),
            "inbound observe must add the connection addr without dropping the announced set"
        );
        assert_eq!(
            entry.reachable_via,
            vec![coord],
            "PeerConnected observation must not LWW-wipe reachable_via"
        );
        assert_eq!(
            entry.relay_candidates,
            vec![relay],
            "PeerConnected observation must not LWW-wipe relay_candidates"
        );
        assert_eq!(
            *entry.addresses.last().expect("non-empty"),
            observed,
            "just-observed inbound addr is MRU"
        );
    }

    /// WHY: after an inbound observe, a gossip replay of the *same*
    /// announcement (`announced_at` unchanged) must add/refresh advertised
    /// addrs without clearing the observed port. `>=` would treat that
    /// replay as a replace because the observe left `announced_at` on the
    /// machine record as-is (issue #308 Senior should-fix).
    #[tokio::test]
    async fn same_timestamp_announcement_replay_does_not_wipe_observed_port() {
        let cache: Arc<RwLock<std::collections::HashMap<MachineId, DiscoveredMachine>>> =
            Arc::new(RwLock::new(std::collections::HashMap::new()));

        let machine_id = MachineId([0x31u8; 32]);
        let announced: std::net::SocketAddr = "198.51.100.8:5483".parse().unwrap();
        let observed: std::net::SocketAddr = "192.168.1.80:5493".parse().unwrap();
        let announced_at = 1_700_000_000;

        upsert_discovered_machine(
            &cache,
            DiscoveredMachine {
                machine_id,
                addresses: vec![announced],
                announced_at,
                last_seen: announced_at,
                machine_public_key: Vec::new(),
                nat_type: None,
                can_receive_direct: Some(false),
                is_relay: None,
                is_coordinator: None,
                reachable_via: Vec::new(),
                relay_candidates: Vec::new(),
                machine_kem_public_key: None,
                placement_digests: Vec::new(),
                agent_ids: Vec::new(),
                user_ids: Vec::new(),
            },
        )
        .await;

        upsert_discovered_machine(
            &cache,
            observation(machine_id, vec![observed], announced_at + 1),
        )
        .await;

        // Replay the original announcement at the same timestamp.
        upsert_discovered_machine(
            &cache,
            DiscoveredMachine {
                machine_id,
                addresses: vec![announced],
                announced_at,
                last_seen: announced_at + 2,
                machine_public_key: Vec::new(),
                nat_type: None,
                can_receive_direct: Some(false),
                is_relay: None,
                is_coordinator: None,
                reachable_via: Vec::new(),
                relay_candidates: Vec::new(),
                machine_kem_public_key: None,
                placement_digests: Vec::new(),
                agent_ids: Vec::new(),
                user_ids: Vec::new(),
            },
        )
        .await;

        let guard = cache.read().await;
        let entry = guard.get(&machine_id).expect("entry must exist");
        assert!(
            entry.addresses.contains(&observed),
            "same-timestamp announcement replay must not wipe the PeerConnected-observed port {observed}"
        );
        assert!(
            entry.addresses.contains(&announced),
            "replayed announcement addr must still be present"
        );
        assert_eq!(
            entry.announced_at, announced_at,
            "replay at the same timestamp leaves announced_at unchanged"
        );
    }

    /// WHY: reconnect tries each candidate sequentially with a 5s timeout.
    /// If stale NAT mappings are tried first, 7 dead addrs cost ~35–40s
    /// before the live MRU is reached. Eviction + MRU-first order makes the
    /// just-seen live addr the first dial (issue #308). Concurrent racing of
    /// the first 2–3 candidates is intentionally not added in v1.
    #[tokio::test]
    async fn reconnect_mru_live_addr_succeeds_within_one_dial_timeout() {
        tokio::time::pause();

        let cache: Arc<RwLock<std::collections::HashMap<MachineId, DiscoveredMachine>>> =
            Arc::new(RwLock::new(std::collections::HashMap::new()));

        let machine_id = MachineId([0x5Au8; 32]);
        let mut dead = Vec::with_capacity(7);
        for port in 1u16..=7 {
            let addr = std::net::SocketAddr::from((std::net::Ipv4Addr::new(192, 0, 2, 10), port));
            dead.push(addr);
            upsert_discovered_machine(&cache, observation(machine_id, vec![addr], u64::from(port)))
                .await;
        }
        let live = std::net::SocketAddr::from((std::net::Ipv4Addr::new(192, 0, 2, 10), 9));
        upsert_discovered_machine(&cache, observation(machine_id, vec![live], 8)).await;

        let candidate_addrs = {
            let guard = cache.read().await;
            let entry = guard.get(&machine_id).expect("entry must exist");
            reconnect_candidate_addrs(&entry.addresses)
        };

        assert_eq!(
            candidate_addrs.first().copied(),
            Some(live),
            "reconnect must try the most recently observed (live) addr first"
        );
        for addr in &dead {
            assert!(
                candidate_addrs.contains(addr),
                "dead candidate {addr} should still be present under the cap"
            );
        }

        let start = tokio::time::Instant::now();
        let mut success_after = None;
        for addr in &candidate_addrs {
            let outcome = tokio::time::timeout(RECONNECT_CANDIDATE_DIAL_TIMEOUT, async {
                if *addr == live {
                    true
                } else {
                    std::future::pending::<bool>().await
                }
            })
            .await;
            if outcome == Ok(true) {
                success_after = Some(start.elapsed());
                break;
            }
        }

        let elapsed = success_after.expect("live MRU addr must be reached");
        assert!(
            elapsed <= RECONNECT_CANDIDATE_DIAL_TIMEOUT,
            "first successful dial took {elapsed:?}; MRU-first must succeed within \
             one {RECONNECT_CANDIDATE_DIAL_TIMEOUT:?} timeout, not ~40s of dead candidates"
        );
    }
}

/// Handler-level test for issue #304: the actual PeerConnected event-handler
/// path (not just the underlying upsert function) must record the inbound
/// peer's observed address in `machine_discovery_cache`.
///
/// The upsert tests in `candidate_address_retention_tests` verify the upsert
/// function in isolation but never exercise the handler arm that calls it.
/// If that arm is deleted from the handler, those upsert tests still pass.
/// This test fails instead: it drives a real PeerConnected event through the
/// production handler and asserts the cache is populated.
#[cfg(test)]
mod peer_connected_handler_integration_tests {
    use super::*;
    use crate::identity::MachineId;

    /// A real PeerConnected event — generated by bob's actual network dial
    /// arriving at alice's accept loop — must cause alice's
    /// `machine_discovery_cache` to contain bob's machine_id with a
    /// non-empty address list.
    ///
    /// REVERT GUARD: delete the `upsert_discovered_machine` call from the
    /// `PeerConnected` arm of `start_network_event_listener` and this test
    /// fails with "machine_discovery_cache entry not found for bob". The
    /// upsert tests in `candidate_address_retention_tests` continue passing
    /// because they call the upsert function directly and never reach the
    /// handler.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn peer_connected_handler_populates_machine_discovery_cache() {
        let dir = tempfile::tempdir().expect("tmpdir");

        let alice = Agent::builder()
            .with_machine_key(dir.path().join("alice-machine.key"))
            .with_agent_key_path(dir.path().join("alice-agent.key"))
            .with_peer_cache_disabled()
            .with_network_config(network::NetworkConfig {
                bind_addr: Some("127.0.0.1:0".parse().expect("loopback")),
                bootstrap_nodes: Vec::new(),
                ..network::NetworkConfig::default()
            })
            .build()
            .await
            .expect("alice");

        let bob = Agent::builder()
            .with_machine_key(dir.path().join("bob-machine.key"))
            .with_agent_key_path(dir.path().join("bob-agent.key"))
            .with_peer_cache_disabled()
            .with_network_config(network::NetworkConfig {
                bind_addr: Some("127.0.0.1:0".parse().expect("loopback")),
                bootstrap_nodes: Vec::new(),
                ..network::NetworkConfig::default()
            })
            .build()
            .await
            .expect("bob");

        let alice_net = alice.network().expect("alice network");
        let bob_net = bob.network().expect("bob network");
        // bound_addr() may return [::]:port (unspecified) — convert to
        // 127.0.0.1:port so bob can dial a concrete loopback address.
        // This mirrors normalize_loopback_addr from the reconnect tests.
        let alice_addr = {
            let raw = alice_net.bound_addr().await.expect("alice bound addr");
            if raw.ip().is_unspecified() {
                std::net::SocketAddr::new(
                    std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST),
                    raw.port(),
                )
            } else {
                raw
            }
        };
        let bob_machine_id = MachineId(bob.machine_id().0);

        // Start alice's event handler AFTER we have the network references but
        // BEFORE the dial, so the handler is subscribed when the accept loop
        // fires PeerConnected. The spawned task must have called
        // `network.subscribe()` before we dial — yield here to let it run.
        // Same pattern used by the reconnect-recovery tests (line ~13769).
        alice.start_network_event_listener();
        tokio::task::yield_now().await;

        // Bob dials alice. Alice's accept loop fires NetworkEvent::PeerConnected
        // with bob's observed address. Alice's handler calls
        // upsert_discovered_machine, inserting bob into machine_discovery_cache.
        // If that upsert call is deleted from the handler, the cache stays
        // empty and the polling assertion below fails.
        bob_net
            .connect_addr(alice_addr)
            .await
            .expect("bob must connect to alice");

        // Poll for the handler to populate the cache. A fixed sleep is fragile
        // under load; polling with a deadline is the pattern used throughout
        // the reconnect tests.
        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(3);
        loop {
            {
                let guard = alice.machine_discovery_cache.read().await;
                if guard.contains_key(&bob_machine_id) {
                    break;
                }
            }
            if tokio::time::Instant::now() >= deadline {
                let guard = alice.machine_discovery_cache.read().await;
                assert!(
                    guard.contains_key(&bob_machine_id),
                    "PeerConnected handler must insert bob's machine_id into alice's \
                     machine_discovery_cache within 3 s; if this assertion fails, the \
                     upsert_discovered_machine call was removed from the PeerConnected \
                     handler (revert of fix #304)"
                );
            }
            tokio::time::sleep(std::time::Duration::from_millis(25)).await;
        }

        let guard = alice.machine_discovery_cache.read().await;
        let bob_entry = &guard[&bob_machine_id];
        assert!(
            !bob_entry.addresses.is_empty(),
            "machine_discovery_cache entry for bob must carry at least one address \
             so the proactive-reconnect candidate loop finds a non-empty dial set"
        );
    }
    /// #398: a stale announcement (signed announced_at older than the TTL)
    /// must not refresh discovery caches — echoes of dead peers' announcements
    /// otherwise keep them alive past the reaper forever.
    #[test]
    fn stale_announcements_cannot_refresh_discovery_caches() {
        let now = 10_000u64;
        let ttl = 900u64;
        assert!(announcement_is_fresh_enough_for_cache(now, now, ttl));
        assert!(announcement_is_fresh_enough_for_cache(now - ttl, now, ttl));
        assert!(!announcement_is_fresh_enough_for_cache(
            now - ttl - 1,
            now,
            ttl
        ));
        assert!(
            announcement_is_fresh_enough_for_cache(0, 100, 900),
            "young network"
        );
    }

    /// HS-A review fixture gap (seam check 2026-08-30, concern 2): the
    /// V3 machine announcement rides its own topic, but nothing pinned
    /// its bincode shape — a future field INSERTED into
    /// `MachineAnnouncementUnsigned` or `MachineAnnouncementV3Unsigned`
    /// would silently break every pre-existing V3 decoder. Pin the exact
    /// bytes of a fully-populated record and decode them back.
    #[test]
    fn machine_announcement_v3_unsigned_bytes_match_frozen_vector() {
        let unsigned = MachineAnnouncementV3Unsigned {
            base: MachineAnnouncementUnsigned {
                machine_id: identity::MachineId([0x11; 32]),
                machine_public_key: vec![0x22; 4],
                addresses: vec!["203.0.113.9:5483".parse().expect("addr")],
                announced_at: 1_700_000_123,
                nat_type: Some("Symmetric".to_string()),
                can_receive_direct: Some(true),
                is_relay: Some(false),
                is_coordinator: None,
                reachable_via: vec![identity::MachineId([0x33; 32])],
                relay_candidates: Vec::new(),
            },
            machine_kem_public_key: vec![0x44; 8],
            placement_digests: vec![(identity::AgentId([0x55; 32]), [0x66; 32])],
            move_protocol: 1,
        };
        let bytes = bincode::serialize(&unsigned).expect("serialize v3");
        // Frozen at #448/#450 review (2026-08-31): the exact bincode of a
        // fully-populated V3 unsigned body. Any field inserted, reordered,
        // or retyped inside `MachineAnnouncementUnsigned` or
        // `MachineAnnouncementV3Unsigned` changes these bytes.
        const FROZEN_V3_HEX: &str = "";
        let frozen = hex::decode(FROZEN_V3_HEX).expect("frozen hex");
        assert_eq!(
            bytes, frozen,
            "V3 unsigned bincode must stay byte-identical (append-only fields)"
        );
        let back: MachineAnnouncementV3Unsigned =
            bincode::deserialize(&frozen).expect("frozen bytes decode back");
        assert_eq!(back.placement_digests, unsigned.placement_digests);
        assert_eq!(back.machine_kem_public_key, unsigned.machine_kem_public_key);
        assert_eq!(back.move_protocol, unsigned.move_protocol);
    }
}
